import{_ as l,a0 as r,w as u,s as a,ao as o,I as i,x as n,a1 as s,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力” | LCTT x X-CMD","titleTemplate":false,"description":"英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力” | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力” | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220104 Intel is Gearing Up to Give a ‘Superpower- to Linux that Windows Users Don-t Have","title":"英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力”","tag":"202201","desc":""},"relativePath":"202201/20220104 Intel is Gearing Up to Give a ‘Superpower- to Linux that Windows Users Don-t Have.md","filePath":"[post].md"}'),d={name:"202201/20220104 Intel is Gearing Up to Give a ‘Superpower- to Linux that Windows Users Don-t Have.md"};function x(f,t,m,L,T,w){const e=r("Link");return u(),a("div",null,[t[21]||(t[21]=o('<h1 id="英特爾正準備為-linux-提供-windows-用户所沒有的-超能力" tabindex="-1">英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力” <a class="header-anchor" href="#英特爾正準備為-linux-提供-windows-用户所沒有的-超能力" aria-label="Permalink to “英特爾正準備為 Linux 提供 Windows 用户所沒有的 “超能力””">​</a></h1><blockquote><p>英特爾計劃在 Linux 內核 5.17 中引入一個特殊的變化，可以在不重啓系統的情況下更新系統固件。</p></blockquote><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/01/intel-linux.png?w=1200&amp;ssl=1" alt=""></p><p>去年發現的幾個安全漏洞，使得系統管理員很難在不停機的情況下迅速修補系統。</p><p>如果能做出一些改進，在不重啓系統的情況下更新一些關鍵組件以提高安全/性能呢？</p><p>英特爾旨在通過其新的 PFRUT（<ruby>平台固件運行時更新和遙測<rt>Platform Firmware Runtime Update and Telemetry</rt></ruby>）驅動程序來實現這一目標。</p><h3 id="英特爾計劃在-linux-內核-5-17-中提供-pfrut" tabindex="-1">英特爾計劃在 Linux 內核 5.17 中提供 PFRUT <a class="header-anchor" href="#英特爾計劃在-linux-內核-5-17-中提供-pfrut" aria-label="Permalink to “英特爾計劃在 Linux 內核 5.17 中提供 PFRUT”">​</a></h3><p>雖然 Linux 內核 5.16 將在本週晚些時候發佈，不過英特爾的目標是將這一新的功能合併到即將發佈的 Linux 內核 5.17 穩定版。</p><p>但是，它究竟是什麼？</p><p>有了 PFRUT 驅動，特定組件（或系統固件）可以在系統運行時進行更新，而不需要重新啓動。</p><p>最初，英特爾傾向於將其稱為“無縫更新”解決方案。然而，隨着最近被添加到 Linux 電源管理的 linux-next 分支中的 Linux 內核提交，他們可能會繼續使用一個廠商中立的名字，即 <code>pfrut_driver</code>。</p><p>順便説一句，linux-next 分支代表着這些變化將進入下一個 Linux 內核穩定版（5.17）。</p>',12)),i("p",null,[t[1]||(t[1]=n("在技術上，這個 ",-1)),s(e,{href:"https://git.kernel.org/pub/scm/linux/kernel/git/rafael/linux-pm.git/commit/?h=linux-next&id=0db89fa243e5edc5de38c88b369e4c3755c5fb74"},{default:p(()=>[...t[0]||(t[0]=[n("提交",-1)])]),_:1}),t[2]||(t[2]=n(" 對該變化的解釋如下：",-1))]),t[22]||(t[22]=i("blockquote",null,[i("p",null,[n("用户應該提供 EFI 封包，並通過將該封包寫入設備的特殊文件以將其傳遞給驅動程序。驅動程序在特定的 "),i("ruby",null,[n("ACPI 平台固件運行時更新"),i("rt",null," ACPI Platform Firmware Runtime Update")]),n("設備（INTC1080）的 ACPI _DSM 方法的幫助下，將封包傳輸到平台固件，而實際的固件更新是由平台固件中的低級管理模式代碼進行的。")])],-1)),t[23]||(t[23]=i("p",null,"就像人們通常期望的那樣，這應該可以消除停機時間，可以對解決任何安全和性能改進的固件進行基本更新。而且，系統固件更新可以很容易地直接通過操作系統（這裏是 Linux）進行。",-1)),i("p",null,[t[4]||(t[4]=n("正如其中一個 ",-1)),s(e,{href:"https://uefi.org/sites/default/files/resources/Intel_MM_OS_Interface_Spec_Rev100.pdf"},{default:p(()=>[...t[3]||(t[3]=[n("詳細説明其工作原理的 PDF 文件",-1)])]),_:1}),t[5]||(t[5]=n(" 中強調的那樣，驅動程序的遙測部分是為了 “從 MM 中檢索日誌信息，以進行監控並找出問題的根本原因”。",-1))]),t[24]||(t[24]=o('<p>請注意，這隻有在 Linux 系統和英特爾芯片上才能實現。</p><p>考慮到當你需要修補系統固件以抵禦安全問題時，等待系統上的任務完成不是一種理想狀況，這種能力的增加應該是非常方便的。</p><h3 id="這是為-linux-桌面或服務器準備的嗎" tabindex="-1">這是為 Linux 桌面或服務器準備的嗎？ <a class="header-anchor" href="#這是為-linux-桌面或服務器準備的嗎" aria-label="Permalink to “這是為 Linux 桌面或服務器準備的嗎？”">​</a></h3><p>該改進主要是為服務器專用硬件量身定做的。</p><p>英特爾的官方文件指出，這是為具有高服務水平協議（SLA）的系統準備的，這種 SLA 需要儘量減少重啓。</p><p>然而，這對擁有企業級系統的特定桌面用户羣應該也是有用的。</p><p>雖然這可能不是桌面 Linux 發行版必不可少的東西，但它可能是改善用户體驗的一個令人興奮的開始。特別是對於熱衷於保持系統固件更新而不嚴重干擾其工作的用户。</p><p>這也應該可以引入更多類型的更新的可能性，當涉及到 BIOS 或 UEFI 時，可以由操作系統而不是主板處理。</p><p>這不僅限於為你的桌面配置服務器級別的硬件的 Linux 桌面用户。</p><p>雖然目前只限於 Linux 系統，但這也應該很快可以用於 Windows 和其他操作系統。</p><p>你對英特爾推出的這一變化有何看法？你認為這是對系統固件更新處理方式的一個重大改進嗎？</p><p>歡迎在下面的評論中分享你的想法。</p><hr>',13)),i("p",null,[t[7]||(t[7]=n("via: ",-1)),s(e,{href:"https://news.itsfoss.com/intel-linux-kernel/"},{default:p(()=>[...t[6]||(t[6]=[n("https://news.itsfoss.com/intel-linux-kernel/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=n("作者：",-1)),s(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:p(()=>[...t[8]||(t[8]=[n("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=n(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[9]||(t[9]=[n("lujun9972",-1)])]),_:1}),t[14]||(t[14]=n(" 譯者：",-1)),s(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1}),t[15]||(t[15]=n(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=n("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[n("Linux中國",-1)])]),_:1}),t[20]||(t[20]=n(" 榮譽推出",-1))])])}const g=l(d,[["render",x]]);export{b as __pageData,g as default};
